<?php
namespace App\Filament\Pages;
use Filament\Pages\Page;
use Illuminate\Support\Facades\DB;
class GiaDashboard extends Page { protected static ?string $navigationLabel='ГИА'; protected static ?string $navigationGroup='Учебная часть'; protected static string $view='filament.pages.gia-dashboard'; public array $campaigns=[],$stats=[]; public function mount():void { $p=request()->attributes->get('academic_period'); if(!$p)return; $rows=DB::table('gia_campaigns as c')->join('study_groups as g','g.id','=','c.study_group_id')->where('c.academic_period_id',$p->id)->select('c.*','g.name as group_name')->orderByDesc('c.id')->get(); $this->campaigns=$rows->map(function($x){$s=DB::table('gia_student_results')->where('gia_campaign_id',$x->id)->get(); return (array)$x+['students'=>$s->count(),'ready'=>$s->whereIn('admission_status',['ready','admitted'])->count(),'blocked'=>$s->where('admission_status','blocked')->count(),'passed'=>$s->where('passed',1)->count()];})->all(); $a=collect($this->campaigns); $this->stats=['campaigns'=>$a->count(),'active'=>$a->where('status','active')->count(),'blocked'=>$a->sum('blocked'),'passed'=>$a->sum('passed')]; } public static function canAccess():bool { $u=auth()->user(); return $u&&($u->isSuperAdmin()||$u->hasRole('admin')||$u->hasRole('head_academic')||$u->hasRole('academic_head')); } }
